class Cart:
    def __init__(
        self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0
    ) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []
        self._discounts = []
        self._vouchers = []

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("quantity must be greater than zero")
        self._items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        """Register a percentage discount on the whole cart."""
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        """Register a voucher worth a fixed amount."""
        self._vouchers.append(amount)

    def total(self) -> float:
        """Amount to pay: items after discounts plus shipping."""
        subtotal = sum(price * quantity for _, price, quantity in self._items)
        item_total = subtotal

        for percent in self._discounts:
            item_total *= 1 - percent / 100

        for amount in self._vouchers:
            item_total = max(0.0, item_total - amount)

        shipping = (
            0.0 if subtotal >= self.free_shipping_threshold else self.shipping_cost
        )
        return round(item_total + shipping, 2)
